// debounce(fn, ms): returns a function that delays calling fn until ms have passed without
// another call; fn gets the arguments of the last call. The returned function has .cancel()
// (drop the pending call) and .flush() (run the pending call now, if any).
export function debounce(fn, ms) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), ms);
  };
}
```

