{"path": "src/debounce.js", "content": "// debounce(fn, ms): returns a function that delays calling fn until ms have passed without
// another call; fn gets the arguments of the last call. The returned function has .cancel()
// (drop the pending call) and .flush() (run the pending call now, if any).
export function debounce(fn, ms) {
  let timer;
  let pendingArgs = null;
  let pendingThis;

  const run = () => {
    const args = pendingArgs;
    const ctx = pendingThis;
    timer = undefined;
    pendingArgs = null;
    pendingThis = undefined;
    return fn.apply(ctx, args);
  };

  function debounced(...args) {
    pendingArgs = args;
    pendingThis = this;
    clearTimeout(timer);
    timer = setTimeout(run, ms);
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = undefined;
    pendingArgs = null;
    pendingThis = undefined;
  };

  debounced.flush = () => {
    if (pendingArgs === null) return undefined;
    clearTimeout(timer);
    return run();
  };

  return debounced;
}
